import * as React from "react";
import type { SVGIconProps } from "../../svgIconProps";
import { IconSize } from "../../iconTypes";
import { SVGIconContainer } from "../../svgIconContainer";

/** Path data for the 16px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_16 = ["M10 2H6V0h4zM0 6v4h2V6zm6 10h4v-2H6zm8-6V6h2v4zM2 0H1a1 1 0 0 0-1 1v3h2V2h2V0zM0 15v-3h2v2h2v2H1a1 1 0 0 1-1-1m14 1h1a1 1 0 0 0 1-1v-3h-2v2h-2v2zm2-15v3h-2V2h-2V0h3a1 1 0 0 1 1 1"] as readonly string[];

/** Path data for the 20px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_20 = ["M5 0H1a1 1 0 0 0-1 1v4h2V2h3zm13 15v3h-3v2h4a1 1 0 0 0 1-1v-4zM0 18v-3h2v3h3v2H1a1 1 0 0 1-1-1zM15 0h4a1 1 0 0 1 1 1v4h-2V2h-3zM8 0h4v2H8zm10 8v4h2V8zM0 12V8h2v4zm12 6H8v2h4z"] as readonly string[];

export const SelectionBoxIcon: React.FC<SVGIconProps> = React.forwardRef<any, SVGIconProps>((props, ref) => {
    const isLarge = (props.size ?? IconSize.STANDARD) >= IconSize.LARGE;
    const paths = isLarge ? PATHS_20 : PATHS_16;
    return (
        <SVGIconContainer iconName="selection-box" ref={ref} {...props}>
            {paths.map((d, i) => (
                <path key={i} d={d} fillRule="evenodd" />
            ))}
        </SVGIconContainer>
    );
});
SelectionBoxIcon.displayName = `Blueprint6.Icon.SelectionBoxIcon`;

/**
 * @deprecated Use {@link SelectionBoxIcon} instead.
 */
export const SelectionBox: typeof SelectionBoxIcon = SelectionBoxIcon;

export default SelectionBoxIcon;
